{
  "packet_id": "H6-T04-1",
  "claim_id": "C048",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C048.component",
    "value": "Like observation windows should be compared because the stated conditions can shift apparent retention.",
    "scope": "A comparability prescription concerning roster timing, team size, acquisition mix and changing onboarding conditions; no guarantee of removing confounding is asserted.",
    "provenance": {
      "refs": [
        {
          "source_id": "P026",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P026 supplies both the comparison prescription and the conditions motivating it."
    }
  },
  "signal_basis": {
    "component_id": "C048.signal_basis",
    "value": "Observed trajectory concentrations differ in milestone position, waiting duration, returns to active work and time to first publication. Follow-up extends through stated roster opportunities plus a grace period, with a fixed maximum for unknown dates; unfinished trajectories are censored and reported alongside published accounts.",
    "scope": "Retention observations in the prospective onboarding cohort, including accounts with no return or incomplete follow-up.",
    "provenance": {
      "refs": [
        {
          "source_id": "P014",
          "role": "SUPPORT"
        },
        {
          "source_id": "P008",
          "role": "SUPPORT"
        },
        {
          "source_id": "P016",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans specify the trajectory signal, observation horizons, censoring and inclusion of unfinished accounts."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C048.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "This component is inapplicable because the judgment is SUPPORTED rather than CONDITIONAL_WARRANT."
    }
  },
  "rationale": "The signal measures progress and waiting over time, so observation windows affect the opportunity to observe returns and publication. Comparing like windows is warranted for interpreting apparent retention amid the stated timing and cohort differences. This limited comparability prescription does not require establishing the magnitude of each condition's influence or claiming that comparable windows eliminate confounding.",
  "uncertainty": "The contribution of each stated condition remains unquantified; that does not undermine the bounded comparison prescription.",
  "anomalies": []
}
